#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Build a portable, offline HTML explanation from the frozen Luna records."""
import hashlib
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
BASE = ROOT / ".cdr/waves/luna-thirty-paired-v1"
read = lambda p: json.loads(p.read_text())
results = read(BASE / "raw-r1-verdicts/results.json")
audit = read(BASE / "audit-results.json")
analysis_file = ROOT / "reports/luna-thirty-error-analysis.json"
error_analysis = read(analysis_file) if analysis_file.exists() else None
cases = {item["id"]: item for item in read(BASE / "cases.json")}
translations = {
    25: "Рамон не станет легендой шахмат.", 30: "Рэйлин создаёт инновационные продукты.",
    47: "Мейджор — не искусный боксёр.", 73: "Лави выступает против экстремизма.",
    105: "Ронан не разрабатывает новые методы.", 127: "Сапфир не совершит революцию в магических практиках.",
    128: "Наталия не бесстрашна.", 152: "Сильвия сделает прорывные открытия.",
    155: "Элина не освоит экстремальные виды спорта.", 198: "Гэри не получает наград.",
    229: "Аманда непрактична.", 230: "Кхай не станет постоянным клиентом.",
    239: "Если Ева столкнулась с неудачей, она может найти новую цель.",
    244: "Детектив Мила скрупулёзна, следует процедурам или внимательна к деталям.",
    263: "Куини быстро размножается.", 292: "Алия не проявляет новаторства.",
    298: "Маппет может принимать обоснованные решения.",
    300: "Если пациенты Стивена получают медицинское лечение, их психическое здоровье может улучшиться.",
    331: "Тейт становится экспертом в своей области.", 336: "Эллис оказывает поддержку.",
    356: "Аделина не вдохновляет других.", 375: "Нора не ценит знания.",
    378: "Доктор Кларк не получает наград.", 381: "Натали не получает признания.",
    404: "Джулиан неорганизован.", 406: "Алана любит приключения.",
    419: "Калани предпочитает пиво массового производства.", 420: "Хантер — неудачливый рыбак.",
    482: "Девин любит приключения, разбирается в истории инков или занимается археологией.",
    489: "Симба не столкнётся с опасностью.",
}
rows = []
for result in results["records"]:
    ident = result["source_id"]
    directory = BASE / f"raw-r1-verdicts/case-{ident}"
    record = read(directory / "record.json")
    program = record["formalization"]["output"]["program"]
    assert hashlib.sha256(program.encode()).hexdigest() == result["program_sha256"]
    transcript = record["execution"]["observation"]["runtime"]["transcript"]["transcript"]
    match = re.search(r",(entailed|contradicted|unknown|conflict|invalid_program|budget_exhausted),", transcript)
    one, two = result["M1"]["answer"] == result["gold"], result["M2"]["answer"] == result["gold"]
    outcome = "both" if one and two else "helped" if two else "worse" if one else "missed"
    rows.append({**result, **cases[ident], "translation": translations[ident], "outcome": outcome,
        "program": program, "query": record["formalization"]["output"]["query"],
        "transcript": transcript, "executor_status": match[1] if match else "unclassified",
        "prompts": {stage: read(directory / stage / "request.json")["prompt"] for stage in ["formalization", "M1", "M2"]}})
assert len(rows) == 30 and sum(r["outcome"] == "helped" for r in rows) == 5
assert audit["unique_model_threads"] == 90 and audit["correct"] == {"M1": 12, "M2": 17}
if error_analysis:
    findings = {case["id"]: case for case in error_analysis["cases"]}
    assert len(findings) == len(error_analysis["cases"]) == 13
    assert set(findings) == {row["id"] for row in rows if row["outcome"] == "missed"}
    assert all(finding["confidence"] in {"confirmed", "likely", "unresolved"} for finding in findings.values())
    for row in rows:
        row["analysis"] = findings.get(row["id"])
data = {"rows": rows, "summary": results["summary"], "audit": audit,
    "error_analysis": error_analysis,
    "error_analysis_sha256": hashlib.sha256(analysis_file.read_bytes()).hexdigest() if error_analysis else None,
    "results_sha256": hashlib.sha256((BASE / "raw-r1-verdicts/results.json").read_bytes()).hexdigest(),
    "commit": "a5be7d6", "manifest_sha256": results["manifest_sha256"]}

